const $=s=>document.querySelector(s);const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',check:'<path d="m5 12 4 4L19 6"/>',checksquare:'<rect x="3" y="3" width="18" height="18" rx="5"/><path d="m8 12 3 3 5-6"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',note:'<path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9z"/><path d="M14 3v6h6M8 13h8M8 17h5"/>',book:'<path d="M12 5v16M3 3c4-1 6 0 9 2 3-2 5-3 9-2v16c-4-1-6 0-9 2-3-2-5-3-9-2z"/>',plane:'<path d="m22 2-7 20-4-9L2 9Z M22 2 11 13"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',shirt:'<path d="m16 3 6 4-3 5-3-2v11H8V10l-3 2-3-5 6-4a4 4 0 0 0 8 0Z"/>',bag:'<path d="M5 7h14l2 14H3L5 7ZM8 8V6a4 4 0 0 1 8 0v2"/>',wallet:'<path d="M20 8V5a2 2 0 0 0-2-2H5a3 3 0 0 0 0 6h16v12H5a3 3 0 0 1-3-3V6M21 12h-5v5h5"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5 19 19M5 19l1.5-1.5M17.5 6.5 19 5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2M14 15h2"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M7 17 17 7M7 7h10v10"/>',right:'<path d="m9 5 7 7-7 7"/>',search:'<circle cx="10.5" cy="10.5" r="7"/><path d="m16 16 5 5"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5ZM20 2v4M18 4h4"/>',up:'<path d="M12 19V5m-6 6 6-6 6 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',dots:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="3"/><path d="M8 7V3h8v4M3 12a20 20 0 0 0 18 0M12 11v4"/>',chat:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H3l2-5a8.5 8.5 0 1 1 16-3.5Z"/>',pen:'<path d="m16 3 5 5-12 12-6 1 1-6ZM14 5l5 5"/>'};function icon(n){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.grid}</svg>`}function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}const categories=[{id:'learn',name:'Học tập',icon:'book',color:'#8f9bc8',bg:'#eff1fa',fg:'#8794bc',desc:'Kiến thức mới, phiên bản mới.'},{id:'goals',name:'Mục tiêu',icon:'target',color:'#dda579',bg:'#fbf0e6',fg:'#c79a72',desc:'Những điều bạn đang hướng tới.'},{id:'travel',name:'Du lịch',icon:'plane',color:'#84b3b4',bg:'#eaf3f3',fg:'#79a5a7',desc:'Những nơi chốn đang chờ bạn.'},{id:'health',name:'Sức khỏe',icon:'heart',color:'#ce9196',bg:'#faedef',fg:'#c0878d',desc:'Một cơ thể khỏe, một tâm trí nhẹ.'},{id:'style',name:'Phong cách',icon:'shirt',color:'#ad9cc2',bg:'#f3eef8',fg:'#a08eb6',desc:'Những gì khiến bạn thấy là mình.'},{id:'shopping',name:'Mua sắm',icon:'bag',color:'#c5af87',bg:'#f8f2e8',fg:'#b69e76',desc:'Mua có chủ đích, dùng thật vui.'},{id:'money',name:'Tài chính',icon:'wallet',color:'#8aaf96',bg:'#edf5ee',fg:'#7ca087',desc:'Chi tiêu hôm nay, an tâm ngày mai.'},{id:'daily',name:'Đời sống',icon:'sun',color:'#d4bd75',bg:'#faf5e4',fg:'#bcaa69',desc:'Những điều nhỏ làm nên mỗi ngày.'}];const workcats=[{id:'content',name:'Content',icon:'pen',color:'#8f9bc8',bg:'#eff1fa',fg:'#8794bc',desc:'Từ một ý tưởng đến bài viết hoàn chỉnh.'},{id:'bots',name:'Bot Zalo',icon:'chat',color:'#84b3b4',bg:'#eaf3f3',fg:'#79a5a7',desc:'Hội thoại cần chú ý, tập trung một chỗ.'},{id:'projects',name:'Dự án',icon:'briefcase',color:'#dda579',bg:'#fbf0e6',fg:'#c79a72',desc:'Từng bước đưa công việc về đích.'},{id:'inbox',name:'Thông tin',icon:'note',color:'#ad9cc2',bg:'#f3eef8',fg:'#a08eb6',desc:'Gom thông tin, tìm điều quan trọng.'}];const allcats=[...categories,...workcats];const cat=id=>allcats.find(c=>c.id===id)||categories[7];const bangkokDate=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());const today=bangkokDate;let state;try{state=JSON.parse(localStorage.getItem('orbit-demo-v1'))}catch{}if(!state||!Array.isArray(state.tasks))state={tasks:[]};if(!state.tasks.length&&!state.initialized){state.tasks=[{id:1,title:'Dành 20 phút học tiếng Anh',category:'learn',date:today,time:'08:30',done:false},{id:2,title:'Yoga & giãn cơ sau giờ làm',category:'health',date:today,time:'18:00',done:false},{id:3,title:'Chuyển tiền vào quỹ du lịch',category:'money',date:today,time:'20:00',done:false},{id:4,title:'Lên dàn ý 3 bài content tuần tới',category:'content',date:today,time:'09:00',done:false},{id:5,title:'Kiểm tra hội thoại bot cần hỗ trợ',category:'bots',date:today,time:'10:30',done:false}]}state.initialized=true;state.notes=state.notes||[{id:101,title:'Những điều muốn thử năm nay',body:'Học một chút tiếng Nhật.\nĐi một chuyến một mình.\nDành nhiều thời gian hơn cho gia đình.',category:'daily'}];state.habits=state.habits||[true,true,true,false,false,false,false];state.savings=state.savings??12000000;state.lessons=state.lessons??13;let space='life',view='overview',filter='all',lastFocus=null;function save(){try{localStorage.setItem('orbit-demo-v1',JSON.stringify(state))}catch{toast('Trình duyệt không cho lưu dữ liệu. Bạn vẫn có thể thử giao diện.')}}function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3800)}function currentCats(){return space==='work'?workcats:space==='all'?allcats:categories}function baseTasks(){return state.tasks.filter(t=>currentCats().some(c=>c.id===t.category))}function viewTasks(){return baseTasks().filter(t=>allcats.some(c=>c.id===view)?t.category===view:true)}function money(n){return new Intl.NumberFormat('vi-VN').format(n)}function tag(c){return `<span class="category-tag" style="--tag-bg:${c.bg};--tag-color:${c.fg}">${icon(c.icon)}${c.name}</span>`}function nav(){const items=[['overview','grid','Tổng quan'],['tasks','checksquare','Việc của tôi'],['targets','target','Mục tiêu'],['notes','note','Ghi nhớ']];$('#mainnav').innerHTML=items.map(([id,i,label])=>`<button class="nav-item ${view===id?'active':''}" data-view="${id}">${icon(i)}<span>${label}</span>${id==='tasks'?`<span class="nav-counter">${baseTasks().filter(t=>!t.done).length}</span>`:''}</button>`).join('');$('#areanav').innerHTML=currentCats().map(c=>`<button class="nav-item ${view===c.id?'active':''}" data-view="${c.id}"><span class="category-dot" style="--color:${c.color}"></span>${c.name}</button>`).join('');$('.areas-label').innerHTML=(space==='work'?'CÁC MẢNG CÔNG VIỆC':'CÁC MẢNG CUỘC SỐNG')+` <span>${String(currentCats().length).padStart(2,'0')}</span>`;$('#crumb').textContent=items.find(x=>x[0]===view)?.[2]||cat(view).name;$('#crumbicon').innerHTML=icon(items.find(x=>x[0]===view)?.[1]||cat(view).icon)}function taskList(tasks){let visible=tasks.filter(t=>filter==='done'?t.done:filter==='pending'?!t.done:true);return `<div class="card"><div class="task-tabs"><button class="${filter==='all'?'active':''}" data-filter="all">Tất cả <span>${tasks.length}</span></button><button class="${filter==='pending'?'active':''}" data-filter="pending">Cần làm <span>${tasks.filter(t=>!t.done).length}</span></button><button class="${filter==='done'?'active':''}" data-filter="done">Đã xong <span>${tasks.filter(t=>t.done).length}</span></button></div>${visible.length?visible.map(t=>`<div class="task-row ${t.done?'done':''}"><input type="checkbox" aria-label="Hoàn thành ${esc(t.title)}" data-task="${t.id}" ${t.done?'checked':''}><div class="task-text"><div class="task-name">${esc(t.title)}</div><div class="task-sub">${tag(cat(t.category))}<span>·</span><span>${t.date===today?'Hôm nay':esc(t.date||'Chưa đặt lịch')}</span></div></div><span class="task-time">${esc(t.time||'')}</span><button class="icon-button delete-task" aria-label="Xóa việc ${esc(t.title)}" data-delete="${t.id}">${icon('trash')}</button></div>`).join(''):`<div class="empty-state">${icon('checksquare')} ${filter==='done'?'Mỗi việc nhỏ hoàn thành đều đáng ghi nhận.':'Không có việc nào trong danh sách này.'}</div>`}<button class="add-inline" data-action="add">${icon('plus')}Thêm một việc nhỏ</button></div>`}function goalItem(type){const learning=type==='learn',pct=learning?Math.min(100,Math.round(state.lessons/20*100)):Math.min(100,Math.round(state.savings/30000000*100));return `<div class="goal-item"><div class="goal-heading"><span class="goal-icon" style="--bg:${learning?'#f0f0fa':'#f0f5ed'};--fg:${learning?'#9a94bf':'#8aab7d'}">${icon(learning?'book':'wallet')}</span><div><strong>${learning?'Tiếng Anh tự tin hơn':'Quỹ du lịch Nhật Bản'}</strong><small>${learning?state.lessons+' / 20 buổi học':money(state.savings)+' / 30.000.000 ₫'}</small></div><span>${pct}%</span></div><div class="bar"><i style="width:${pct}%;background:${learning?'#b0a8cf':'#a7bf96'}"></i></div></div>`}function goals(){return `<section class="card goal-card"><div class="inner-heading"><h3>Mục tiêu đang theo đuổi</h3>${icon('target')}</div>${goalItem('learn')}${goalItem('money')}<div class="goal-footer"><button class="text-button" data-view="targets">Từng bước, đúng hướng ${icon('arrow')}</button></div></section>`}function assistant(){return `<section class="assistant-card"><div class="assistant-top"><div class="assistant-title"><span class="assistant-symbol">✳</span>Orbit Assistant</div><span class="assistant-mode">PREVIEW</span></div><p class="assistant-subtitle">Một người bạn, hiểu những điều bạn đang lo.</p><div class="ai-bubble"><div class="ai-overline">${icon('spark')}MỘT GỢI Ý DÀNH CHO BẠN</div><p id="aireply">Tuần này bạn đã dành nhiều thời gian cho công việc.<br><br>Hay mình giữ lại <strong>một buổi tối không deadline</strong>, chỉ để làm điều bạn thích?</p><button class="ai-link" data-prompt="nghỉ">Tìm một khoảng nghỉ ${icon('arrow')}</button></div><div class="suggestions"><button data-prompt="ưu tiên">${icon('checksquare')}Hôm nay lo gì?</button><button data-prompt="tiết kiệm">${icon('wallet')}Quỹ tiết kiệm</button></div><form class="chat-form" id="chatform"><textarea id="chatinput" aria-label="Nhắn Orbit" placeholder="Mình đang nghĩ đến…" maxlength="1000"></textarea><div class="chat-form-bottom"><span>${icon('lock')}Không gian của bạn</span><button type="submit" aria-label="Gửi tin nhắn">${icon('up')}</button></div></form><p class="demo-note">Trợ lý minh họa · Chưa kết nối AI</p></section>`}function habit(){return `<div class="card habit-card"><div class="habit-top"><strong>20 phút cho một điều mới</strong><span>✧ &nbsp; Học mỗi ngày</span></div><p class="habit-description">Một chút đều đặn, một thay đổi lớn.</p><div class="week-activity">${['T2','T3','T4','T5','T6','T7','CN'].map((d,i)=>`<div class="habit-day"><span>${d}</span><button class="${state.habits[i]?'checked':''} ${i===3?'current':''}" data-habit="${i}" aria-label="${d}: ${state.habits[i]?'Đã học':'Đánh dấu đã học'}" aria-pressed="${state.habits[i]}">${state.habits[i]?icon('check'):i===3?'<span>12</span>':''}</button></div>`).join('')}</div><div class="habit-bottom"><span>Tuần minh họa · 09 – 15/11</span><strong>${state.habits.filter(Boolean).length}/7 ngày</strong></div></div>`}function trip(){return `<div class="card trip-card"><img src="assets/japan.jpg" alt="Con phố cổ và tháp Yasaka tại Kyoto, Nhật Bản"><div class="trip-top"><span class="trip-badge">${icon('plane')}CHUYẾN ĐI MƠ ƯỚC</span><button data-action="trip" aria-label="Xem kế hoạch Nhật Bản">${icon('arrow')}</button></div><div class="trip-bottom"><span class="overline">MỘT NƠI ĐỂ MONG CHỜ</span><h3>Kyoto, someday.</h3><p>Nhật Bản · Mùa thu 2027</p><div class="trip-budget"><span>Quỹ cho một chuyến đi</span><span>${Math.round(state.savings/30000000*100)}%</span></div><div class="bar"><i style="width:${Math.min(100,state.savings/30000000*100)}%"></i></div></div></div>`}function areas(){return `<div class="section-heading"><h2>${space==='work'?'Mọi việc, đúng chỗ':'Cuộc sống có nhiều mảnh ghép'}</h2><span class="text-button">${currentCats().length} không gian riêng</span></div><div class="area-strip">${currentCats().map(c=>`<button class="area-tile" data-view="${c.id}" style="--bg:${c.bg};--fg:${c.fg}"><span class="area-icon">${icon(c.icon)}</span><span><strong>${c.name}</strong><small>${state.tasks.filter(t=>t.category===c.id&&!t.done).length} việc đang chờ</small></span>${icon('right')}</button>`).join('')}</div>`}function dashboard(){const tasks=baseTasks(),done=tasks.filter(t=>t.done).length,pending=tasks.length-done;return `<div class="dashboard-layout"><div class="dashboard-left"><section class="insight-banner"><div class="sun-illustration">${icon('sun')}</div><div><strong>Không cần làm hết. Chỉ cần đúng điều quan trọng.</strong><p>Bạn có ${pending} việc đang chờ. Bắt đầu bằng một việc nhỏ, phần còn lại cứ từ từ.</p></div><button class="banner-link" data-view="tasks" aria-label="Xem việc cần làm">${icon('arrow')}</button></section><div class="stats-grid"><div class="stat-card"><div class="stat-top">Việc đang chờ ${icon('checksquare')}</div><div class="stat-number">${String(pending).padStart(2,'0')}<small>việc</small></div><div class="stat-bottom"><span class="positive">${done} đã xong</span> Từng việc một, nhẹ đầu hơn</div></div><div class="stat-card"><div class="stat-top">Mục tiêu cá nhân ${icon('target')}</div><div class="stat-number">02<small>mục tiêu</small></div><div class="stat-mini-bars">${[9,15,12,21,18,25,30].map(h=>`<i style="height:${h}px"></i>`).join('')}</div><div class="stat-bottom"><span class="positive">Đang tiến bước</span> Giữ nhịp của mình</div></div><div class="stat-card"><div class="stat-top">Quỹ tiết kiệm ${icon('wallet')}</div><div class="stat-number">${(state.savings/1000000).toLocaleString('vi-VN')}<small>triệu ₫</small></div><div class="stat-bottom"><span class="positive">${Math.round(state.savings/30000000*100)}% mục tiêu</span> Cho chuyến đi mơ ước</div></div></div>${areas()}<section class="task-section"><div class="section-heading"><h2>Những việc cần quan tâm <span>${String(tasks.length).padStart(2,'0')}</span></h2><button class="text-button" data-view="tasks">Xem tất cả ${icon('arrow')}</button></div>${taskList(tasks)}</section><div class="bottom-grid"><section><div class="section-heading"><h2>Thói quen nhỏ, mỗi ngày</h2>${icon('dots')}</div>${habit()}</section><section><div class="section-heading"><h2>Dành chỗ cho trải nghiệm</h2><button class="text-button" data-action="trip">Khám phá ${icon('arrow')}</button></div>${trip()}</section></div></div><div class="right-column">${assistant()}${goals()}<div class="breather"><span>MỘT LỜI NHẮC NHỎ</span><p>“Bạn cũng là một người<br>cần được <span>bạn chăm sóc.</span>”</p></div></div></div>`}function render(){nav();const overview=view==='overview';const title=overview?(space==='work'?'Rõ việc, nhẹ đầu.':space==='all'?'Mọi điều, một không gian.':'Một ngày tốt lành, bạn nhé.'):{tasks:'Từng việc một, rồi sẽ xong.',targets:'Gần hơn với điều mình muốn.',notes:'Giữ lại những điều đáng nhớ.'}[view]||cat(view).name;$('#greeting').innerHTML=title+(overview?'<span class="wave">☀️</span>':'');$('#intro').textContent=overview?(space==='work'?'Ý tưởng, dự án, hội thoại — nhìn rõ những gì đang chạy.':'Bớt một chút bộn bề. Thêm một chút thời gian cho mình.'):{tasks:'Một nơi cho những việc cần làm, một nhịp độ do bạn chọn.',targets:'Tiến độ không cần nhanh. Chỉ cần vẫn đang bước tới.',notes:'Ý tưởng thoáng qua, một điều cần nhớ, hay một lời hứa với mình.'}[view]||cat(view).desc;$('#add').innerHTML=icon('plus')+(view==='notes'?'Thêm ghi nhớ':'Thêm điều cần nhớ');if(overview)$('#content').innerHTML=dashboard();else if(view==='notes')$('#content').innerHTML=`<div class="notes-grid">${state.notes.map(n=>`<article class="note">${tag(cat(n.category))}<h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><small>Ghi nhớ cá nhân · Lưu trên trình duyệt</small></article>`).join('')}</div>`;else if(view==='targets')$('#content').innerHTML=`<div class="big-goals"><div class="card goal-card">${goalItem('learn')}<p class="modal-info">Dành 20 phút cho một buổi học. Mỗi lần hoàn thành là thêm một bước tiến.</p><button class="button secondary" data-action="lesson">${icon('plus')}Ghi nhận một buổi học</button></div><div class="card goal-card">${goalItem('money')}<p class="modal-info">Mục tiêu 30 triệu cho chuyến Nhật Bản. Ghi nhận khoản bạn đã dành riêng.</p><button class="button secondary" data-action="saving">${icon('plus')}Cập nhật quỹ tiết kiệm</button></div></div>`;else{const c=cat(view);$('#content').innerHTML=`<div class="list-view">${view==='tasks'?'':`<section class="category-hero" style="--bg:${c.bg};--fg:${c.fg}"><span class="area-icon">${icon(c.icon)}</span><div><h2>${c.name}, theo cách của bạn.</h2><p>${c.desc}</p></div></section>`}${taskList(viewTasks())}${view==='travel'?`<div style="max-width:450px;margin-top:23px">${trip()}</div>`:''}</div>`}bindChat();document.querySelectorAll('[data-space]').forEach(b=>b.classList.toggle('active',b.dataset.space===space));save()}function setView(v){view=v;filter='all';render();document.body.classList.remove('sidebar-open')}function showModal(title,html){lastFocus=document.activeElement;$('#modaltitle').textContent=title;$('#modalbody').innerHTML=html;$('#modal').classList.add('visible');setTimeout(()=>$('#modalbody').querySelector('input,textarea,button')?.focus(),20)}function closeModal(){$('#modal').classList.remove('visible');lastFocus?.focus()}function addModal(prefill='',kind=view==='notes'?'note':'task'){showModal(kind==='note'?'Giữ lại một điều gì đó':'Thêm một điều cần nhớ',`<form id="entryform"><label for="entrytitle">${kind==='note'?'Tiêu đề ghi nhớ':'Điều bạn muốn làm'}</label><input class="field" id="entrytitle" placeholder="${kind==='note'?'Một ý tưởng vừa nghĩ ra…':'Ví dụ: Dành 20 phút đọc sách'}" value="${esc(prefill)}" required maxlength="180">${kind==='note'?'<label for="entrybody">Nội dung</label><textarea class="field" id="entrybody" placeholder="Cứ viết những gì bạn đang nghĩ…" maxlength="5000"></textarea>':''}<div class="form-row"><div><label for="entrycategory">Thuộc mảng nào?</label><select class="field" id="entrycategory">${currentCats().map(c=>`<option value="${c.id}" ${c.id===view?'selected':''}>${c.name}</option>`).join('')}</select></div>${kind==='task'?`<div><label for="entrydate">Ngày dự định</label><input class="field" id="entrydate" type="date" value="${today}"></div>`:''}</div><p class="modal-info">${icon('lock')} Lưu trên trình duyệt này. Chưa đồng bộ hoặc gửi thông báo.</p><div class="modal-actions"><button type="button" class="button secondary" data-action="close">Để sau</button><button type="submit" class="button primary">Lưu lại ${icon('check')}</button></div></form>`);$('#entryform').onsubmit=e=>{e.preventDefault();const title=$('#entrytitle').value.trim();if(!title)return;const category=$('#entrycategory').value;if(kind==='note')state.notes.unshift({id:Date.now(),title,category,body:$('#entrybody').value.trim()});else state.tasks.push({id:Date.now(),title,category,date:$('#entrydate').value,time:'',done:false});save();closeModal();filter='all';render();toast('Đã lưu lại. Thêm một điều bớt phải nhớ trong đầu.')}}function calendar(){const tasks=baseTasks().filter(t=>t.date&&!t.done).sort((a,b)=>a.date.localeCompare(b.date)||(a.time||'').localeCompare(b.time||''));showModal('Lịch trình của bạn',`<div class="calendar-list">${tasks.length?tasks.map(t=>`<div class="calendar-entry"><div class="date-box">${esc(t.date.split('-').reverse().slice(0,2).join('/'))}</div><div><strong>${esc(t.title)}</strong><p>${cat(t.category).name} · ${esc(t.time||'Chưa đặt giờ')}</p></div></div>`).join(''):'<p class="modal-info">Chưa có việc nào được đặt lịch.</p>'}</div><p class="modal-info">Lịch theo dữ liệu demo và những việc bạn thêm.</p>`)}function search(){showModal('Bạn đang tìm điều gì?',`<input id="searchfield" class="field" placeholder="Tìm việc, ghi nhớ, không gian…" aria-label="Tìm kiếm"><div class="search-results" id="results"></div>`);function results(){const q=$('#searchfield').value.trim().toLocaleLowerCase('vi');const list=[...allcats.map(c=>({title:c.name,view:c.id,icon:c.icon})),...state.tasks.map(t=>({title:t.title,view:t.category,icon:'checksquare'})),...state.notes.map(n=>({title:n.title,view:'notes',icon:'note'}))].filter(x=>x.title.toLocaleLowerCase('vi').includes(q)).slice(0,10);$('#results').innerHTML=list.length?list.map(x=>`<button class="result" data-result="${x.view}">${icon(x.icon)}${esc(x.title)}</button>`).join(''):'<div class="empty-state">Chưa tìm thấy kết quả.</div>'}$('#searchfield').oninput=results;results()}function reply(q){const s=q.toLocaleLowerCase('vi');let text;if(/tiết kiệm|tiền|quỹ/.test(s)){const left=Math.max(0,30000000-state.savings);text=`Quỹ Nhật Bản hiện có ${money(state.savings)} ₫, còn ${money(left)} ₫ để đạt mục tiêu. Nếu dành thêm 3 triệu mỗi tháng, bạn cần khoảng ${Math.ceil(left/3000000)} tháng nữa. Đây là phép tính từ dữ liệu mẫu.`}else if(/nghỉ|cuối tuần/.test(s))text='Một gợi ý nhỏ: giữ lại 60 phút sáng Chủ nhật cho đi bộ, cà phê hoặc đọc sách. Chưa cần lấp đầy khoảng nghỉ bằng một mục tiêu khác. Đây là gợi ý minh họa, chưa kiểm tra lịch thật của bạn.';else if(/nhắc|ghi|thêm/.test(s)){text='Mình đã mở biểu mẫu. Bạn chọn ngày và mảng phù hợp rồi lưu lại nhé. Bản demo chưa gửi thông báo tự động.';addModal(q)}else{const t=baseTasks().find(t=>!t.done);text=t?`Bắt đầu với “${t.title}” nhé. Làm xong một việc nhỏ rồi nhìn lại các việc tiếp theo. Đây là gợi ý dựa trên danh sách của bạn, chưa gọi AI.`:'Bạn đã hoàn thành các việc trong không gian này. Một khoảng trống cũng là điều tốt. Nếu có điều mới, mình có thể giúp bạn ghi lại.'}if($('#aireply'))$('#aireply').textContent=text;else toast(text)}function bindChat(){if($('#chatform'))$('#chatform').onsubmit=e=>{e.preventDefault();const q=$('#chatinput').value.trim();if(q){reply(q);$('#chatinput').value=''}}}function action(a){if(a==='add')addModal();if(a==='close')closeModal();if(a==='trip')showModal('Kyoto, mùa thu 2027',`<img src="assets/japan.jpg" alt="Kyoto, Nhật Bản" style="width:100%;height:190px;object-fit:cover;border-radius:9px"><p class="modal-detail">Một chuyến đi để mong chờ. Dự kiến 7 ngày khám phá Kyoto và Osaka, với ngân sách mục tiêu <strong>30 triệu đồng</strong>.</p><div class="goal-card" style="padding:10px 0">${goalItem('money')}</div><p class="modal-info">Kế hoạch mẫu: chọn thời gian → tìm vé → đặt chỗ ở → lập lịch khám phá. Bạn có thể thêm từng việc vào mảng Du lịch.</p><div class="modal-actions"><button class="button primary" data-action="tripadd">${icon('plus')}Thêm việc chuẩn bị</button></div>`);if(a==='tripadd'){space='life';view='travel';render();addModal('Tìm vé cho chuyến Nhật Bản')}if(a==='lesson'){state.lessons=Math.min(20,state.lessons+1);save();render();toast('Đã ghi nhận thêm một buổi học. Cứ đều đặn nhé!')}if(a==='saving'){showModal('Dành thêm cho chuyến đi',`<form id="savingform"><label for="amount">Số tiền bổ sung (₫)</label><input class="field" type="number" id="amount" min="1" max="1000000000" step="1" required placeholder="Ví dụ: 1.000.000"><p class="modal-info">Đây là ghi nhận thủ công, không thực hiện giao dịch ngân hàng.</p><div class="modal-actions"><button class="button primary">Ghi nhận khoản tiết kiệm</button></div></form>`);$('#savingform').onsubmit=e=>{e.preventDefault();const n=Number($('#amount').value);if(n>0&&n<=1e9){state.savings+=n;save();closeModal();render();toast('Quỹ du lịch đã được cập nhật.')}}}}document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){if(workcats.some(c=>c.id===b.dataset.view)&&space==='life')space='work';if(categories.some(c=>c.id===b.dataset.view)&&space==='work')space='life';setView(b.dataset.view)}if(b.dataset.space){space=b.dataset.space;setView('overview')}if(b.dataset.filter){filter=b.dataset.filter;render()}if(b.dataset.action)action(b.dataset.action);if(b.dataset.prompt)reply(b.dataset.prompt);if(b.dataset.habit!==undefined){const i=Number(b.dataset.habit);state.habits[i]=!state.habits[i];save();render();toast(state.habits[i]?'Một chút tốt hơn mỗi ngày. Đã ghi nhận!':'Đã bỏ đánh dấu ngày học.')}if(b.dataset.delete){state.tasks=state.tasks.filter(t=>String(t.id)!==b.dataset.delete);save();render();toast('Đã xóa việc khỏi danh sách.')}if(b.dataset.result){const v=b.dataset.result;closeModal();space=workcats.some(c=>c.id===v)?'work':'life';setView(v)}});document.addEventListener('change',e=>{if(e.target.dataset.task){const t=state.tasks.find(t=>String(t.id)===e.target.dataset.task);if(t){t.done=e.target.checked;save();render();if(t.done)toast('Thêm một việc hoàn thành. Bạn làm tốt rồi.')}}});$('#add').onclick=()=>addModal();$('#calendar').innerHTML=icon('calendar')+'Lịch trình';$('#calendar').onclick=calendar;$('#searchicon').innerHTML=icon('search');$('#notification').innerHTML=icon('bell');$('#notification').onclick=()=>toast('Chưa có thông báo. Nhắc việc chạy nền chưa được bật trong demo.');$('#mobilemenu').innerHTML=icon('menu');$('#mobilemenu').onclick=()=>document.body.classList.toggle('sidebar-open');$('#sideoverlay').onclick=()=>document.body.classList.remove('sidebar-open');$('#closemodal').innerHTML=icon('close');$('#closemodal').onclick=closeModal;$('#modal').onclick=e=>{if(e.target===$('#modal'))closeModal()};$('#search').onclick=search;$('#tipbutton').onclick=()=>addModal('','note');$('#workspace').onclick=()=>toast('Không gian cá nhân · Dữ liệu lưu riêng trên trình duyệt này.');$('.brand').onclick=e=>{e.preventDefault();setView('overview')};function credits(){showModal('Orbit — Your life, in focus',`<div class="modal-detail">Một bản thử nghiệm cho ý tưởng trợ lý quản lý công việc và cuộc sống.<br><br>Thiết kế tham khảo cách phân cấp dashboard của <a href="https://github.com/zerostaticthemes/square-ui/tree/master/templates/dashboard-5" target="_blank" rel="noopener">Square UI — Dashboard 5</a>. Giao diện này được viết riêng cho Orbit, chưa tích hợp bộ component React của repo.<br><br>Ảnh Kyoto: <a href="https://unsplash.com/photos/1493976040374-85c8e12f0c0e" target="_blank" rel="noopener">Unsplash</a>.</div><p class="modal-info">Dữ liệu mẫu · Lưu trên trình duyệt · Chưa kết nối AI hoặc ứng dụng ngoài.</p>`)}$('#about').onclick=credits;$('#credits').onclick=credits;document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();document.body.classList.remove('sidebar-open')}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();search()}if(e.key==='Tab'&&$('#modal').classList.contains('visible')){const nodes=[...$('#modal').querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});$('#date').innerHTML=icon('calendar')+esc(new Intl.DateTimeFormat('vi-VN',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Bangkok'}).format(new Date()));render();
